class HelperMethod {

    private static final log = LogFactory.getLog(this)

    public static String getContentTypeOfFile(File tempFile, String password) {
        def contentTypeStr
        try {
            contentTypeStr = ('file --mime-type ' + tempFile).execute()?.text
        } catch (IOException ioe) {
        }
        contentTypeStr = contentTypeStr && StringUtils.isNotBlank(contentTypeStr) ? contentTypeStr.split(':')[1].trim() : null
        if (!contentTypeStr || contentTypeStr.equals("application/octet-stream")) {
            contentTypeStr = fetchContentTypeUsingTika(tempFile, password)
