    public static String cleanPipes(String sourceString) {
        if (!sourceString.trim()) {
            return sourceString
        }
        String modifiedString = sourceString.replaceAll("[\\|]{2,10}", "|").trim()
        if (modifiedString.charAt(0) == "|".toCharacter()) {
            modifiedString = modifiedString.replaceFirst("[\\|]", "")
        }
        if (modifiedString.charAt(modifiedString.length() - 1) == "|".toCharacter()) {
            modifiedString = modifiedString.substring(0, modifiedString.length() - 1)
        }
        modifiedString.trim()
    }

    public static List<String> tokenizeString(String str) {
        List<String> keywords = ['lic', 'phd', 'ani', 'pvr']
        List<String> strList = str.toLowerCase()?.replaceAll('-', ' ')?.replaceAll('_', ' ')?.replaceAll('/', ' ')?.split(' ') ?: []
        strList.removeAll([''])
        strList.removeAll { it.length() <= 3 && keywords.intersect([it]).size() == 0 }
        strList = strList.collect { it.replaceAll("[0-9]+", "") }
        strList = strList.collect { it.replaceAll("^[-|_|/]+|[-|_|/]+\$", "") }
        strList.removeAll(['from', 'by', 'to'])
        strList.removeAll { it.matches("^[0-9]+\$") }
        strList.removeAll { it.matches("^x+\$") }
        strList.removeAll { it.matches("\\s+") }
        strList.removeAll { it.length() <= 2 }
        strList
    }

