    public static List<File> splitPdfDocument(File pdfFile, String password = null) {
        List<File> pdfFiles = []
        PdfReader reader = password ? new PdfReader(pdfFile.bytes, password.bytes) : new PdfReader(pdfFile.bytes)
        int n = reader.getNumberOfPages()
        reader.unethicalreading = true
        LogEntry.debug("Number of pages : " + n)
        int i = 0
        while (i < n) {
            File tempPdfFile = File.createTempFile("${RandomStringUtils.random(7)}", ".pdf")
            Document document = new Document(reader.getPageSizeWithRotation(1))
            PdfCopy writer = new PdfCopy(document, new FileOutputStream(tempPdfFile))
            document.open()
            PdfImportedPage page = writer.getImportedPage(reader, ++i)
            writer.addPage(page)
            document.close()
            writer.close()
            pdfFiles << tempPdfFile
        }
        pdfFiles
    }

