    public static String removeNumberFromEitherEndOfString(String str) {
        if (!str || StringUtils.isBlank(str))
            return null
        else {
            str = str.trim().replaceAll("^[0-9]+", "")
            str = str.replaceAll("[0-9]+\$", "")
            return str
