    public static String removeSpecialCharsFromEitherEndOfString(String str) {
        if (!str || StringUtils.isBlank(str))
            return null
        else {
            str = str.replaceAll("\\(inr\\)[\\s]*\$", "")
            str = str.trim().replaceAll("(^[\\s]*<)|(>[\\s]*\$)", "")
            str = str.trim().replaceAll("^-|^/|^\\(-\\)", "")
            str = str.replaceAll("-\$|/\$|\\(-\\)\$", "")
            str = str.replaceAll("\\(|\\)", "")       //New method yet to check
            str = str.replaceAll(",", "")
            str = str.replaceAll("[\\s]", "")
            str = str.replaceAll("l", "1")
            str = str.replaceAll("[CcDd][\\s]*[Rrb][.]?|c", "")
            str = str.replaceAll("[\\*]", "")
            str = str.trim()
            return str
        }
    }

