public static enum StaticFileStorageTarget {
    AZURE, GOOGLE
}

class HelperMethod {

    private static final log = LogFactory.getLog(this)

    /** Config key holding the bucket used for storing static files on Google Cloud Storage. */
    public static final String GOOGLE_CLOUD_STORAGE_BUCKET_CONFIG_KEY = "google.cloud.storage.bucket.name"

    /** Config key pointing to the classpath resource of the service account used by Google Cloud Storage. */
    public static final String GOOGLE_CLOUD_CREDENTIALS_CONFIG_KEY = "google.cloud.storage.credentials.resource"

    /** Config key holding the Google Cloud project owning the bucket. */
    public static final String GOOGLE_CLOUD_PROJECT_CONFIG_KEY = "google.cloud.storage.project.id"

    /**
     * Classpath locations searched for the (optional) service account of the deployed runtime.
     * Nothing is bundled with the sources, the deployment supplies one of these resources.
     */
    public static final List<String> GOOGLE_CLOUD_CREDENTIALS_RESOURCES = [
            "google-cloud-storage-service-account.json",
            "google-cloud-service-account.json",
            "google-service-account.json"
    ].asImmutable()

    /** Bucket used when neither the configuration nor the environment declares one. */
    public static final String DEFAULT_GOOGLE_CLOUD_STORAGE_BUCKET_NAME = "bank-scraper-static-files"

