private static String fetchGoogleCloudStorageConfig(String configKey, String environmentKey) {
    String value = null
    try {
        value = Holders.getFlatConfig()?.get(configKey)?.toString()
    }
    catch (Exception e) {
        log.debug("Unable to read '${configKey}' from configuration ==>> ${e.message}")
    }
    if (!value || StringUtils.isBlank(value)) {
        try {
            value = System.getProperty(environmentKey) ?: System.getenv(environmentKey)
        }
        catch (Exception e) {
            log.debug("Unable to read '${environmentKey}' from the environment ==>> ${e.message}")
        }
    }
    value && StringUtils.isNotBlank(value) ? value.trim() : null
}

public static String getGoogleCloudStorageBucketName() {
    fetchGoogleCloudStorageConfig(GOOGLE_CLOUD_STORAGE_BUCKET_CONFIG_KEY,
            "GOOGLE_CLOUD_STORAGE_BUCKET") ?: DEFAULT_GOOGLE_CLOUD_STORAGE_BUCKET_NAME
}

/**
 * Loads the credentials of the service account shipped with the deployed runtime as a classpath
 * resource. Nothing is stored in the repository, so a missing resource simply means that the
 * ambient (application default) credentials of the runtime have to be used.
 */
private static GoogleCredentials fetchGoogleCloudCredentials() {
    GoogleCredentials credentials = null
    List<String> resources = []
    String configuredResource = fetchGoogleCloudStorageConfig(GOOGLE_CLOUD_CREDENTIALS_CONFIG_KEY,
            "GOOGLE_CLOUD_STORAGE_CREDENTIALS_RESOURCE")
    if (configuredResource)
        resources << configuredResource
    resources.addAll(GOOGLE_CLOUD_CREDENTIALS_RESOURCES)
    ClassLoader classLoader = HelperMethod.class.classLoader ?: Thread.currentThread().contextClassLoader
    for (String resource : resources) {
        InputStream credentialsStream = null
        try {
            credentialsStream = classLoader?.getResourceAsStream(resource) ?:
                    Thread.currentThread().contextClassLoader?.getResourceAsStream(resource)
            if (credentialsStream) {
                credentials = GoogleCredentials.fromStream(credentialsStream)
                log.info("=== Using Google Cloud service account from classpath resource ===>>> ${resource}")
                break
            }
        }
        catch (Exception e) {
            log.error("Exception while reading Google Cloud service account '${resource}' ==>> ${e.message}", e)
        }
        finally {
            if (credentialsStream)
                credentialsStream.close()
        }
    }
    credentials
}

/**
 * @return the configured Google Cloud {@link Storage} service, falling back to the ambient
 * credentials of the runtime whenever no service account resource is available.
 */
public static Storage getGoogleCloudStorageService() {
    Storage storage = null
    try {
        StorageOptions.Builder optionsBuilder = StorageOptions.newBuilder()
        GoogleCredentials credentials = fetchGoogleCloudCredentials()
        if (credentials)
            optionsBuilder.setCredentials(credentials)
        String projectId = fetchGoogleCloudStorageConfig(GOOGLE_CLOUD_PROJECT_CONFIG_KEY, "GOOGLE_CLOUD_PROJECT")
        if (projectId)
            optionsBuilder.setProjectId(projectId)
        storage = optionsBuilder.build()?.getService()
    }
    catch (Exception e) {
        log.error("Exception while building Google Cloud Storage service ==>> ${e.message}", e)
        try {
            storage = StorageOptions.getDefaultInstance()?.getService()
        }
        catch (Exception exception) {
            log.error("Exception while fetching default Google Cloud Storage service ==>> ${exception.message}", exception)
        }
    }
    storage
}

public static Boolean uploadObjectToGoogleCloudStorage(File file, String path) {
    Boolean isFileUploaded = Boolean.FALSE
    if (path && StringUtils.isNotBlank(path)) {
        try {
            Storage storage = getGoogleCloudStorageService()
            BlobId blobId = BlobId.of(getGoogleCloudStorageBucketName(), path)
            BlobInfo blobInfo = BlobInfo.newBuilder(blobId).build()
            storage.create(blobInfo, file.getBytes())
            isFileUploaded = Boolean.TRUE
        }
        catch (Exception e) {
            log.error("Exception while uploading file to Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileUploaded
}

public static InputStream downloadObjectFromGoogleCloudStorage(String path) {
    InputStream inputStream = null
    if (path && StringUtils.isNotBlank(path)) {
        try {
            Storage storage = getGoogleCloudStorageService()
            BlobId blobId = BlobId.of(getGoogleCloudStorageBucketName(), path)
            byte[] content = null
            try {
                content = storage.readAllBytes(blobId)
            }
            catch (Exception e) {
                log.debug("Unable to read bytes of '${path}' directly ==>> ${e.message}")
            }
            if (content == null) {
                Blob blob = storage.get(blobId)
                if (blob)
                    content = blob.getContent()
            }
            if (content != null)
                inputStream = new ByteArrayInputStream(content)
        }
        catch (Exception e) {
            log.error("Exception while downloading file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    inputStream
}

public static Boolean deleteObjectFromGoogleCloudStorage(String path) {
    Boolean isFileDeleted = Boolean.FALSE
    if (path && StringUtils.isNotBlank(path)) {
        try {
            Storage storage = getGoogleCloudStorageService()
            isFileDeleted = storage.delete(BlobId.of(getGoogleCloudStorageBucketName(), path)) as Boolean
        }
        catch (Exception e) {
            log.error("Exception while deleting file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileDeleted
}

