/**
 * Builds a {@link Storage} service out of {@link StorageOptions}. When no credentials are handed
 * over, {@link StorageOptions} resolves the ambient (application default) credentials itself.
 */
private static Storage buildGoogleCloudStorageService(GoogleCredentials credentials) {
    Storage storage = null
    try {
        StorageOptions.Builder optionsBuilder = StorageOptions.newBuilder()
        if (credentials)
            optionsBuilder.setCredentials(credentials)
        String projectId = fetchGoogleCloudStorageConfig(GOOGLE_CLOUD_PROJECT_CONFIG_KEY, "GOOGLE_CLOUD_PROJECT")
        if (projectId)
            optionsBuilder.setProjectId(projectId)
        storage = optionsBuilder.build()?.getService()
    }
    catch (Throwable t) {
        log.error("Exception while building Google Cloud Storage service ==>> ${t.message}", t)
    }
    storage
}

/**
 * @return the configured Google Cloud {@link Storage} service. The service account supplied by the
 * deployed runtime as a classpath resource is used when present, otherwise the ambient/default
 * credentials of the runtime are used.
 */
public static Storage getGoogleCloudStorageService() {
    GoogleCredentials credentials = fetchGoogleCloudCredentials()
    Storage storage = credentials ? buildGoogleCloudStorageService(credentials) : null
    if (!storage) {
        try {
            storage = StorageOptions.getDefaultInstance()?.getService()
        }
        catch (Throwable t) {
            log.error("Exception while fetching default Google Cloud Storage service ==>> ${t.message}", t)
        }
    }
    if (!storage)
        storage = buildGoogleCloudStorageService(credentials)
    storage
}

/**
 * @return every {@link Storage} service which can be resolved for the current runtime, the
 * configured one first. More than one entry is only ever used when the preferred service is not
 * able to serve a request.
 */
private static List<Storage> fetchGoogleCloudStorageServices() {
    List<Storage> storageServices = []
    List<Closure<Storage>> strategies = [
            { -> getGoogleCloudStorageService() },
            { -> StorageOptions.getDefaultInstance()?.getService() },
            { -> buildGoogleCloudStorageService(fetchGoogleCloudCredentials()) }
    ]
    strategies.each { Closure<Storage> strategy ->
        try {
            Storage storage = strategy.call()
            if (storage && !storageServices.any { it.is(storage) })
                storageServices << storage
        }
        catch (Throwable t) {
            log.debug("Unable to resolve a Google Cloud Storage service ==>> ${t.message}")
        }
    }
    storageServices
}

