/**
 * Executes the given operation against the configured Google Cloud {@link Storage} service and
 * retries it with the remaining resolution strategies as long as no result could be produced.
 *
 * @return the result of the operation or <code>null</code> when it could not be performed
 */
private static def executeOnGoogleCloudStorage(Closure operation) {
    List<Storage> attemptedServices = []
    for (Closure<Storage> strategy : fetchGoogleCloudStorageServiceStrategies()) {
        Storage storage = null
        try {
            storage = strategy.call()
        }
        catch (Throwable t) {
            log.debug("Unable to resolve a Google Cloud Storage service ==>> ${t.message}")
        }
        if (!storage || attemptedServices.any { it.is(storage) })
            continue
        attemptedServices << storage
        try {
            def result = operation.call(storage)
            if (result != null)
                return result
        }
        catch (Throwable t) {
            log.error("Exception while accessing Google Cloud Storage ==>> ${t.message}", t)
        }
    }
    null
}

